/**
 * Tunes Gradle for a memory-constrained build machine.
 *
 * The `android/` folder is generated by `expo prebuild` and is gitignored, so
 * hand-edits to android/gradle.properties are wiped the next time a native
 * package or permission changes. This config plugin rewrites those properties
 * on every prebuild instead, which means the settings actually stick.
 *
 * Why each one, on a 6 GB laptop:
 *
 *   org.gradle.parallel=false
 *     Parallel mode compiles independent modules simultaneously, each in its
 *     own JVM. Fine with 32 GB, fatal with 6 — the workers get starved and die
 *     with "Failed to run Gradle Worker Daemon", which reads like a Gradle bug
 *     rather than an out-of-memory condition.
 *
 *   kotlin.compiler.execution.strategy=in-process
 *     By default Kotlin compiles in a *separate* daemon on top of the Gradle
 *     daemon — two large JVMs at once. In-process reuses the Gradle daemon's
 *     heap. Slightly slower per build, but it is the difference between
 *     building and not building here.
 *
 *   org.gradle.jvmargs=-Xmx1536m
 *     Leaves headroom for the OS, the Metro bundler and the editor. Setting
 *     this *higher* on a small machine makes things worse, not better: the JVM
 *     reserves the heap and the OS starts swapping.
 *
 *   reactNativeArchitectures=arm64-v8a
 *     The default builds four CPU architectures. Every physical Android phone
 *     shipped in years is arm64, so the other three are compiled and then
 *     thrown away. This is the single biggest time saving of the lot.
 *
 * If you are on a larger machine, delete this plugin from app.json — the
 * defaults will build faster.
 */

const { withGradleProperties } = require('expo/config-plugins');

const PROPERTIES = {
  'org.gradle.jvmargs': '-Xmx1536m -XX:MaxMetaspaceSize=512m',
  'org.gradle.parallel': 'false',
  'org.gradle.workers.max': '1',
  'org.gradle.daemon': 'true',
  'kotlin.compiler.execution.strategy': 'in-process',
  'kotlin.incremental': 'true',
  reactNativeArchitectures: 'arm64-v8a',
};

module.exports = function withLowMemoryGradle(config) {
  return withGradleProperties(config, (cfg) => {
    for (const [key, value] of Object.entries(PROPERTIES)) {
      const existing = cfg.modResults.findIndex(
        (item) => item.type === 'property' && item.key === key,
      );
      const entry = { type: 'property', key, value };
      if (existing >= 0) {
        cfg.modResults[existing] = entry;
      } else {
        cfg.modResults.push(entry);
      }
    }
    return cfg;
  });
};
